INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64255291', 64255291, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'RSU DR KARIADI SEMARANG', 'Kontrak Servis Mesin Sterilisasi Suhu Rendah (EO) Merk 3M Tahun 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'Jawa Tengah, Semarang (Kota)', 266400000, 'January 2026', 'APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', 'Kontrak Servis Mesin Sterilisasi Suhu Rendah (EO) Merk 3M Tahun 2026', '1. Pekerjaan Tune Up Mesin 3M SteriVac Type 8XL-1DSN 300544, 2. Pekerjaan Preventive maintenance kit assembly Mesin 3M SteriVac Type GS8-1DSN CA000153 Lingkup Pekerjaan a. Membersihkan Water trap dan mengganti kedua Filter udara masing masing 0.3 Micron dan 0.1 micron. b. Membersihkan dan Mengganti Plunger pada RH Solenoid. c. Membersihkan dan Mengganti Plunger pada Vacuum solenoid. d. Memeriksa sambungan dan Saluran Vent line dan memastikan tidak ada kebocoran dan tidak ada yang menyumbat pada saluran tersebut. e. Mengganti Bacterial Filter. f. Membersihkan dan mengganti Plunger pada solenoid Water Injection dan mengganti saluran ( tubing ) pada jalur dari water reservoir ke Solenoid water injection. g. Membersihkan kotoran pada Water Tank / reservoir. h. Membersihkan system Ventury dan mengganti semua O ring beserta check Valve nya pada system Ventury tersebut. i. Bersihkan dan ganti Plunger pada Solenoid Puncture. j. Memeriksa cyclinder system Puncture dan Mencoba unjuk kerjanya. k. Memeriksa kebersihan Seal door Chamber dan Latch Solenoid berserta Cylindernya, dari kebocoran udara tekan. l. Membersihkan Area controler board dari Debu dan kotoran lain yang dapat menyebabkan hubungan pendek. m. Membersihkan keseluruhan Mesin dalam ruangan Chamber, pintu chamber dan external mesin. n. Melakukan KALIBRASI – mengembalikan settingan beberapa sensor ( Temperature – Vacuum – RH ). ( Bagus/Tepat – Standard Calibration Certificate – Side set up ). o. Melakukan unjuk kerja Barcode Scanner dengan mnggunakan Barcode Reader test Cartridge, ( PASS - Special Tools – Diagnostics Test ) p. Melakukan ”Dead End Test” Meyakinkan test tersebut PASS . ( Pass – Special Tools – Diagnostics Test). q. Melakukan Test Diagnostics pada Chamber test 1 ( Kebocroran Chamber pada tingkat vacuum tinggi ) ( PASS - Dianostic Test ). r. Melakukan Test Diagnostics pada Chamber test 2 ( Kebocroran Chamber pada tingkat vacuum rendah ) ( PASS - Dianostic Test ). s. Melakaukan Test Puncture pada Proses Accelerated Test pada suhu 38C . ( PASS – Special Tools - Accelerated Test ) t. Melakukan Functional Test dengan menggunakan Gas dan Begitu juga beberapa PCD untuk menunjukan kerataan penyebaran Gas pada setiap bagian keranjang. ( PASS/Steril – Functional Test )', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1446567);
